using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Http;
using AlKhayal.Api.Contracts;
using AlKhayal.Application.Authentication;
using AlKhayal.Application.Features;
using AlKhayal.Application.Sales;
using AlKhayal.Application.Users;
using AlKhayal.Core.Models;

namespace AlKhayal.Api.Controllers
{
    [RoutePrefix("api/sales")]
    public sealed class SalesController : ApiController
    {
        private readonly SalesService _sales;private readonly AuthService _auth;private readonly UserManagementService _users;private readonly FeatureService _features;
        public SalesController(SalesService sales,AuthService auth,UserManagementService users,FeatureService features){_sales=sales;_auth=auth;_users=users;_features=features;}
        [HttpGet,Route("")] public async Task<IHttpActionResult> List(string search=null,string from=null,string to=null,CancellationToken ct=default(CancellationToken)){var a=await Require(ct,false).ConfigureAwait(false);if(a.Error!=null)return a.Error;try{return Ok(ApiEnvelope<object>.Ok(await _sales.ListAsync(search,from,to,ct).ConfigureAwait(false)));}catch(ArgumentException ex){return Bad(ex.Message);}}
        [HttpGet,Route("{id:long}")] public async Task<IHttpActionResult> Get(long id,CancellationToken ct){var a=await Require(ct,false).ConfigureAwait(false);if(a.Error!=null)return a.Error;var sale=await _sales.GetAsync(id,ct).ConfigureAwait(false);return sale==null?Content(HttpStatusCode.NotFound,ApiEnvelope<object>.Fail("not_found","الفاتورة غير موجودة.")):Ok(ApiEnvelope<SaleInvoice>.Ok(sale));}
        [HttpPost,Route("drafts")] public async Task<IHttpActionResult> Create(SaleRequest request,CancellationToken ct){var a=await Require(ct,true).ConfigureAwait(false);if(a.Error!=null)return a.Error;try{return Content(HttpStatusCode.Created,ApiEnvelope<SaleInvoice>.Ok(await _sales.CreateDraftAsync(Map(request),a.User.Id,ct).ConfigureAwait(false)));}catch(ArgumentException ex){return Bad(ex.Message);}catch(System.Data.SQLite.SQLiteException){return Conflict("تعذر حفظ مسودة الفاتورة.");}}
        [HttpPut,Route("{id:long}")] public async Task<IHttpActionResult> Update(long id,SaleRequest request,CancellationToken ct){var a=await Require(ct,true).ConfigureAwait(false);if(a.Error!=null)return a.Error;try{var sale=await _sales.UpdateDraftAsync(id,Map(request),a.User.Id,ct).ConfigureAwait(false);return sale==null?Content(HttpStatusCode.NotFound,ApiEnvelope<object>.Fail("not_found","الفاتورة غير موجودة.")):Ok(ApiEnvelope<SaleInvoice>.Ok(sale));}catch(ArgumentException ex){return Bad(ex.Message);}catch(InvalidOperationException ex){return Conflict(ex.Message);}catch(System.Data.SQLite.SQLiteException){return Conflict("تعذر حفظ مسودة الفاتورة.");}}
        [HttpPost,Route("{id:long}/post")] public async Task<IHttpActionResult> Post(long id,SalePostRequest request,CancellationToken ct){var a=await Require(ct,true).ConfigureAwait(false);if(a.Error!=null)return a.Error;var result=await _sales.PostAsync(id,request==null?null:request.OperationKey,a.User.Id,ct).ConfigureAwait(false);if(result==null)return Content(HttpStatusCode.NotFound,ApiEnvelope<object>.Fail("not_found","الفاتورة غير موجودة."));if(!result.Succeeded)return Content(result.ErrorCode=="not_found"?HttpStatusCode.NotFound:result.ErrorCode=="invalid_operation"?HttpStatusCode.BadRequest:HttpStatusCode.Conflict,ApiEnvelope<object>.Fail(result.ErrorCode,result.ErrorMessage));return Ok(ApiEnvelope<SaleInvoice>.Ok(result.Invoice));}
        [HttpPost,Route("{id:long}/payments")] public async Task<IHttpActionResult> Payment(long id,SalePaymentRequest request,CancellationToken ct){var a=await Require(ct,true).ConfigureAwait(false);if(a.Error!=null)return a.Error;try{var result=await _sales.AddPaymentAsync(id,request==null?null:new SalePaymentCommand{Amount=request.Amount,Method=request.Method,OperationKey=request.OperationKey,OccurredOn=request.OccurredOn,Notes=request.Notes},a.User.Id,ct).ConfigureAwait(false);if(result==null)return Content(HttpStatusCode.NotFound,ApiEnvelope<object>.Fail("not_found","الفاتورة غير موجودة."));if(!result.Succeeded)return Content(result.ErrorCode=="validation"?HttpStatusCode.BadRequest:HttpStatusCode.Conflict,ApiEnvelope<object>.Fail(result.ErrorCode,result.ErrorMessage));return Ok(ApiEnvelope<SalePaymentResult>.Ok(result));}catch(ArgumentException ex){return Bad(ex.Message);}}
        [HttpPost,Route("{id:long}/returns")] public async Task<IHttpActionResult> Return(long id,SaleReturnRequest request,CancellationToken ct){var a=await Require(ct,true,"sales-returns").ConfigureAwait(false);if(a.Error!=null)return a.Error;try{var command=request==null?null:new SaleReturnCommand{OperationKey=request.OperationKey,Reason=request.Reason,Lines=(request.Lines??new List<SaleReturnLineRequest>()).Select(x=>x==null?null:new SaleReturnLineCommand{InvoiceLineId=x.InvoiceLineId,Quantity=x.Quantity,Serials=x.Serials??new List<string>()}).ToList()};var result=await _sales.ReturnAsync(id,command,a.User.Id,ct).ConfigureAwait(false);if(result==null)return Content(HttpStatusCode.NotFound,ApiEnvelope<object>.Fail("not_found","الفاتورة غير موجودة."));if(!result.Succeeded)return Content(result.ErrorCode=="validation"?HttpStatusCode.BadRequest:HttpStatusCode.Conflict,ApiEnvelope<object>.Fail(result.ErrorCode,result.ErrorMessage));return Ok(ApiEnvelope<SaleReturnResult>.Ok(result));}catch(ArgumentException ex){return Bad(ex.Message);}}
        [HttpPost,Route("{id:long}/delete-draft")] public async Task<IHttpActionResult> DeleteDraft(long id,SalePostRequest request,CancellationToken ct){var a=await Require(ct,true,"sales-list").ConfigureAwait(false);if(a.Error!=null)return a.Error;var result=await _sales.DeleteDraftAsync(id,request==null?null:request.OperationKey,a.User.Id,ct).ConfigureAwait(false);return CancellationResponse(result);}
        [HttpPost,Route("{id:long}/cancel")] public async Task<IHttpActionResult> Cancel(long id,SaleCancelRequest request,CancellationToken ct){var a=await Require(ct,true,"sales-list").ConfigureAwait(false);if(a.Error!=null)return a.Error;var result=await _sales.CancelAsync(id,request==null?null:request.OperationKey,request==null?null:request.Reason,a.User.Id,ct).ConfigureAwait(false);return CancellationResponse(result);}
        private IHttpActionResult CancellationResponse(SaleCancellationResult result){if(!result.Succeeded)return Content(result.ErrorCode=="not_found"?HttpStatusCode.NotFound:result.ErrorCode=="validation"?HttpStatusCode.BadRequest:HttpStatusCode.Conflict,ApiEnvelope<object>.Fail(result.ErrorCode,result.ErrorMessage));return Ok(ApiEnvelope<SaleCancellationResult>.Ok(result));}
        private async Task<AuthCheck> Require(CancellationToken ct,bool write,string requiredScreen=null){var token=ReadCookie();var user=await _auth.GetCurrentUserAsync(token,ct).ConfigureAwait(false);if(user==null)return new AuthCheck{Error=Content(HttpStatusCode.Unauthorized,ApiEnvelope<object>.Fail("unauthorized","يرجى تسجيل الدخول أولًا."))};if(user.Role!=UserRoles.Administrator){var access=await _users.GetEffectiveAccessAsync(user,await _features.GetEffectiveAsync(ct).ConfigureAwait(false),ct).ConfigureAwait(false);if(requiredScreen!=null?!access.ScreenIds.Contains(requiredScreen,StringComparer.OrdinalIgnoreCase):!new[]{"pos","sales-management","sales-list","sales-returns"}.Any(x=>access.ScreenIds.Contains(x,StringComparer.OrdinalIgnoreCase)))return new AuthCheck{Error=Content(HttpStatusCode.Forbidden,ApiEnvelope<object>.Fail("screen_forbidden","لا تملك صلاحية شاشة المبيعات."))};}if(write&&!await _auth.ValidateCsrfAsync(token,ReadHeader("X-CSRF-Token"),ct).ConfigureAwait(false))return new AuthCheck{Error=Content(HttpStatusCode.Forbidden,ApiEnvelope<object>.Fail("invalid_csrf","تعذر التحقق من الطلب. حدّث الصفحة وحاول مرة أخرى."))};return new AuthCheck{User=user};}
        private static SaleDraftCommand Map(SaleRequest r){if(r==null)return null;return new SaleDraftCommand{PaymentAmount=r.PaymentAmount??r.Amount,HasPaymentAllocations=r.Payments!=null,CustomerId=r.CustomerId,WarehouseId=r.WarehouseId,InvoiceDate=r.InvoiceDate,PaymentMode=r.PaymentMode,ImmediateMethod=r.ImmediateMethod,PaymentInstrumentId=r.PaymentInstrumentId,Discount=r.Discount,Lines=(r.Lines??new List<SaleLineRequest>()).Select(x=>x==null?null:new SaleLine{VariantId=x.VariantId,ProductUnitId=x.ProductUnitId,Quantity=x.Quantity,UnitPrice=x.UnitPrice,Discount=x.Discount,BatchLotNumber=x.LotNumber,ExpirationDate=x.ExpirationDate,PhysicalUnits=x.PhysicalUnits??new List<SaleTrackingUnit>()}).ToList()};}
        private IHttpActionResult Bad(string m){return Content(HttpStatusCode.BadRequest,ApiEnvelope<object>.Fail("validation",m));}private IHttpActionResult Conflict(string m){return Content(HttpStatusCode.Conflict,ApiEnvelope<object>.Fail("sales_conflict",m));}
        private string ReadCookie(){IEnumerable<string> values;if(!Request.Headers.TryGetValues("Cookie",out values))return null;foreach(var header in values)foreach(var part in header.Split(';')){var pair=part.Trim().Split(new[]{'='},2);if(pair.Length==2&&pair[0]=="alkhayal_session")return pair[1];}return null;}private string ReadHeader(string n){IEnumerable<string> values;return Request.Headers.TryGetValues(n,out values)?values.FirstOrDefault():null;}
        private sealed class AuthCheck{public UserIdentity User{get;set;}public IHttpActionResult Error{get;set;}}
    }
    public sealed class SaleRequest{public string Amount{get;set;}public string PaymentAmount{get;set;}public List<SalePaymentRequest> Payments{get;set;}public string ImmediateMethod{get;set;}public long? PaymentInstrumentId{get;set;}public long? CustomerId{get;set;}public long WarehouseId{get;set;}public string InvoiceDate{get;set;}public string PaymentMode{get;set;}public string Discount{get;set;}public List<SaleLineRequest> Lines{get;set;}}
    public sealed class SaleLineRequest{public long VariantId{get;set;}public long ProductUnitId{get;set;}public string Quantity{get;set;}public string UnitPrice{get;set;}public string Discount{get;set;}public string LotNumber{get;set;}public string ExpirationDate{get;set;}public List<SaleTrackingUnit> PhysicalUnits{get;set;}}
    public sealed class SalePostRequest{public string OperationKey{get;set;}}
    public sealed class SaleCancelRequest{public string OperationKey{get;set;}public string Reason{get;set;}}
    public sealed class SalePaymentRequest{public string Amount{get;set;}public string Method{get;set;}public string OperationKey{get;set;}public string OccurredOn{get;set;}public string Notes{get;set;}}
    public sealed class SaleReturnRequest{public string OperationKey{get;set;}public string Reason{get;set;}public List<SaleReturnLineRequest> Lines{get;set;}}
    public sealed class SaleReturnLineRequest{public long InvoiceLineId{get;set;}public string Quantity{get;set;}public List<string> Serials{get;set;}}
}
